                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   return ProjectsResponse(total=len(results), cached=is_cached, projects=results)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
